head.script:
///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name btn_layerClose_onclick
 * @description [Close] 클릭 — 부모 스코프($c.win.getParent) 경유로 레이어(id)를 닫고, 부모가 없으면 자기 자신을 닫는다($c.win.closePopup 폴백).
 * @returns {void}
 * @hidden N
 * @example (a_334 ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_layerClose_onclick = function () {
    // 연 쪽(부모)이 닫는다 — 부모 스코프($c.win.getParent) 경유 id 닫기, 폴백 = 자기 닫기($c.win.closePopup).
    const id = 'jldfil35700_layer_layer1';
    try {
        const pa = (typeof $c !== 'undefined' && $c.win && $c.win.getParent) ? $c.win.getParent() : null;
        if (pa && pa.closePopup) {
            pa.closePopup(id);
            return;
        }
    } catch (e) {
        $c.exception.handleError(e, { notify: 'none', context: 'layerClose' });
    }
    try {
        if (typeof $c !== 'undefined' && $c.win && $c.win.closePopup) $c.win.closePopup();
    } catch (e) {
        $c.exception.handleError(e, { notify: 'none', context: 'layerClose' });
    }
};
